from collections import Counter

PER_BOOK = 800.0
PER_GROUP = {1: PER_BOOK, 2: 1520.0, 3: 2160.0, 4: 2560.0, 5: 3000.0}


def _total(basket):
    copies = sorted(Counter(basket).values(), reverse=True)
    copies.append(0)
    groups = Counter()
    for size in range(1, len(copies)):
        groups[size] = copies[size - 1] - copies[size]

    # Moving one title from a group of five to a group of three saves 40 cents.
    pairs = min(groups[3], groups[5])
    groups[3] -= pairs
    groups[5] -= pairs
    groups[4] += 2 * pairs
    return sum(count * PER_GROUP[size] for size, count in groups.items())


def total(basket):
    if not basket:
        return 0
    return _total(basket)

